// Simple TCP proxy: listens on $listen_port, forwards to $target_host:$target_port
$listen_port = 9999;
$target_host = '10.10.2.2';
$target_port = 5432;

$server = stream_socket_server("tcp://0.0.0.0:$listen_port", $errno, $errstr);
if (!$server) {
    die("Failed to create server: $errstr ($errno)\\n");
}

// Accept one connection and proxy it
$client = @stream_socket_accept($server, 30);
if (!$client) {
    fclose($server);
    die("No connection received\\n");
}

$target = stream_socket_client("tcp://$target_host:$target_port", $errno, $errstr, 10);
if (!$target) {
    fclose($client);
    fclose($server);
    die("Failed to connect to target: $errstr ($errno)\\n");
}

// Set non-blocking for bidirectional relay
stream_set_blocking($client, false);
stream_set_blocking($target, false);

$timeout = time() + 30;
while (time() < $timeout) {
    $read = array($client, $target);
    $write = null;
    $except = null;

